from abc import abstractmethod, ABC
import logging
from pathlib import Path
import tempfile

from taf.internal.managedobject import ManagedObject

from .scf_information_provider import ScfInformationProvider

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class OamInformationProvider(ManagedObject, ABC):
    """
    OAM information provider abstract base class.
    """
    def __init__(self, managed_oam_connection, **kwargs):
        """
        Constructor.

        :param Union[ManagedSbtsAdminConnection, ManagedCoamCUConnection, ManagedVduConnection] managed_oam_connection:
            Managed O&M connection for SBTS, vCU or vDU.
        """
        super().__init__(**kwargs)
        self._managed_oam_connection = managed_oam_connection
        self.add_prerequisite(managed_oam_connection)
        self._scf_information_provider = None

    def _setup(self):
        self._scf_information_provider = ScfInformationProvider(
            scf_content=self._get_scf_content())

    def _get_scf_content(self):
        with tempfile.NamedTemporaryFile() as temp_file:
            path = Path(temp_file.name)
            self._store_current_scf(path)
            return self._read_scf(path)

    def _read_scf(self, path):
        return path.read_bytes()

    @abstractmethod
    def _store_current_scf(self, path):
        """
        Store the current SCF at the local path "path".

        :param Path path: Local path to store the SCF.
        """

    def get_nr_cell_dist_names(self):
        dist_names = self._scf_information_provider.get_nr_cell_dist_names()
        logger.debug(f"NR cell distinguished names: {dist_names}")
        return dist_names

    def get_mplane_ip_address(self):
        mplane_ip_addr = self._scf_information_provider.get_mplane_ip_address()
        logger.debug(f"M-plane IP address: {mplane_ip_addr}", )
        return mplane_ip_addr


class SbtsOamInformationProvider(OamInformationProvider):
    """
    SBTS OAM information provider using ADMIN API via taf.sbts.oam.coam.admin.
    """

    def _store_current_scf(self, path):
        self._managed_oam_connection.get_current_scf_file(
            local_dir_path=str(path.parent),
            file_name=str(path.name),
            export_type="configurationAndRuntimeObjects")


class VcuOamInformationProvider(OamInformationProvider):
    """
    vCU OAM information provider using OAMCU REST API via taf.gnb.oam.coam.cu.
    """

    def _store_current_scf(self, path):
        self._managed_oam_connection.get_current_plan_file(
            path=str(path),
            include_runtime_data=True)


class VduOamInformationProvider(OamInformationProvider):
    """
    vDU OAM information provider using OAMCU REST API via taf.gnb.oam.coam.vdu.
    """

    def _store_current_scf(self, path):
        self._managed_oam_connection.get_current_plan_file(
            path=str(path.parent),
            filename=str(path.name),
            include_runtime_data=True)
